0:
http-address :8080
log-level info
log-format json

# One notification per alert rather than per Alertmanager group, so
# the title names the alert instead of an alert count.
alert-mode single

labels {
    order "severity"

    severity "critical" {
        priority 5
        tags "rotating_light"
    }

    severity "warning" {
        priority 4
        tags "warning"
    }

    severity "info" {
        priority 2
        tags "information_source"
    }
}

resolved {
    update-notification true
    tags "white_check_mark"
    priority 2
}

ntfy {
    server http://ntfy.observability.svc.cluster.local
    topic home-ops
    markdown true
    # Button linking back to the firing expression in Prometheus.
    # prometheusSpec.externalUrl is an envoy-internal hostname, so
    # this resolves on the LAN and not from the wider internet.
    generator-url-label source
}

# No `alertmanager` block on purpose. Its Silence button proxies the
# API call back through this service, which would mean publishing
# base-url somewhere the phone can reach — a third tailnet device to
# keep alive for a convenience button. Silence from the Alertmanager
# UI instead.

cache {
    type memory
    duration 24h
    cleanup-interval 1h
}

{{ range .Alerts -}}
**Alert:** {{ .Annotations.title }}{{ if .Labels.severity }} - `{{ .Labels.severity }}`{{ end }}

{{ if ne .Annotations.summary ""}}**Summary:** {{ .Annotations.summary }}{{ else if ne .Annotations.message ""}}**Message:** {{ .Annotations.message }}{{ else if ne .Annotations.description ""}}**Description:** {{ .Annotations.description }}{{ end }}

🏷 **Labels:**
{{ range .Labels.SortedPairs }} • {{ .Name }}: {{ .Value }}
{{ end }}
{{ end }}
